def _align_frame(self, other, join='outer', axis=None, level=None, copy:
    bool_t=True, fill_value=None, method=None, limit=None, fill_axis=0):
    join_index, join_columns = None, None
    ilidx, iridx = None, None
    clidx, cridx = None, None
    is_series = isinstance(self, ABCSeries)
    if axis is None or axis == 0:
        if not self.index.equals(other.index):
            join_index, ilidx, iridx = self.index.join(other.index, how=
                join, level=level, return_indexers=True)
    if axis is None or axis == 1:
        if not is_series and not self.columns.equals(other.columns):
            join_columns, clidx, cridx = self.columns.join(other.columns,
                how=join, level=level, return_indexers=True)
    if is_series:
        reindexers = {(0): [join_index, ilidx]}
    else:
        reindexers = {(0): [join_index, ilidx], (1): [join_columns, clidx]}
    left = self._reindex_with_indexers(reindexers, copy=copy, fill_value=
        fill_value, allow_dups=True)
    right = other._reindex_with_indexers({(0): [join_index, iridx], (1): [
        join_columns, cridx]}, copy=copy, fill_value=fill_value, allow_dups
        =True)
    if method is not None:
        _left = left.fillna(method=method, axis=fill_axis, limit=limit)
        assert _left is not None
        left = _left
        right = right.fillna(method=method, axis=fill_axis, limit=limit)
    if is_datetime64tz_dtype(left.index.dtype):
        if left.index.tz != right.index.tz:
            if join_index is not None:
                left = left.copy()
                right = right.copy()
                left.index = join_index
                right.index = join_index
    return left.__finalize__(self), right.__finalize__(other)

